import type { SiteData } from "./types";

/** Public R2 dev URL — fallback when site.json / build env omit media_cdn_base. */
export const DEFAULT_MEDIA_CDN =
  "https://pub-a2cd33f89e3643ef948208e821e1a9f5.r2.dev";

const MEDIA_FIELDS = ["thumb", "thumb_full", "src", "url"] as const;

export function resolveMediaCdnBase(data: SiteData): string {
  return (
    data.media_cdn_base ||
    import.meta.env.VITE_MEDIA_CDN_BASE ||
    DEFAULT_MEDIA_CDN
  ).replace(/\/$/, "");
}

/** Rewrite photos/thumbs/... to absolute R2 URLs. */
export function applyMediaCdn(data: SiteData): SiteData {
  const base = resolveMediaCdnBase(data);
  if (!base) return data;

  const rewrite = (value: unknown): unknown => {
    if (Array.isArray(value)) {
      return value.map(rewrite);
    }
    if (value && typeof value === "object") {
      const out: Record<string, unknown> = { ...(value as Record<string, unknown>) };
      for (const field of MEDIA_FIELDS) {
        const path = out[field];
        if (typeof path === "string" && path.startsWith("photos/")) {
          out[field] = `${base}/${path}`;
        }
      }
      for (const key of Object.keys(out)) {
        out[key] = rewrite(out[key]);
      }
      return out;
    }
    return value;
  };

  return {
    ...data,
    trips: rewrite(data.trips) as SiteData["trips"],
  };
}
